<?php namespace App\Http\Controllers\Public; use App\Http\Controllers\Controller; use Illuminate\Http\Request; class NotificationController extends Controller { public function index(Request $request){$user=$request->user();$items=$user->notifications()->latest()->limit(20)->get()->map(fn($item)=>$this->format($item));return response()->json(['unread_count'=>$user->unreadNotifications()->count(),'notifications'=>$items]);} public function read(Request $request,string $notification){$item=$request->user()->notifications()->whereKey($notification)->firstOrFail();$item->markAsRead();return response()->json(['notification'=>$this->format($item->fresh())]);} public function readAll(Request $request){$request->user()->unreadNotifications()->update(['read_at'=>now()]);return response()->json(['message'=>'Notifications marked as read.']);} private function format($item):array{return ['id'=>$item->id,'title'=>$item->data['title']??'Marketplace update','body'=>$item->data['body']??'','url'=>$item->data['url']??null,'kind'=>$item->data['kind']??'general','read_at'=>$item->read_at,'created_at'=>$item->created_at];} }
